const item = $input.item.json;
const formData = $('Form - Upload Empty Room Photo').first().json;

const stagedImageUrl = item.stagedImageUrl || item.staged_image_url || '';
const walkthrough3dUrl = item.walkthrough3dUrl || item['3d_walkthrough_url'] || '';
const styleApplied = item.styleApplied || item.style || 'Modern';

const comparables = item.comparables || item.comps || [];

const prices = comparables
  .map(c => parseFloat(c.price))
  .filter(p => !isNaN(p) && p > 0);

const avgCompPrice = prices.length
  ? Math.round(prices.reduce((sum, p) => sum + p, 0) / prices.length)
  : null;

const pricePerSqftValues = comparables
  .map(c => {
    const p = parseFloat(c.price);
    const s = parseFloat(c.squareFeet || c.sqft);
    return (!isNaN(p) && !isNaN(s) && s > 0) ? p / s : null;
  })
  .filter(v => v !== null);

const avgPricePerSqft = pricePerSqftValues.length
  ? Math.round((pricePerSqftValues.reduce((sum, v) => sum + v, 0) / pricePerSqftValues.length) * 100) / 100
  : null;

const squareFeet = parseFloat(formData['Square Feet']) || 0;

const estimatedValueFromComps = avgPricePerSqft && squareFeet
  ? Math.round(avgPricePerSqft * squareFeet)
  : avgCompPrice;

const suggestedPriceLow = estimatedValueFromComps ? Math.round(estimatedValueFromComps * 0.97) : null;
const suggestedPriceHigh = estimatedValueFromComps ? Math.round(estimatedValueFromComps * 1.03) : null;

return {
  json: {
    address: formData['Property Address'],
    propertyType: formData['Property Type'],
    bedrooms: parseInt(formData['Bedrooms'], 10) || 0,
    bathrooms: parseFloat(formData['Bathrooms']) || 0,
    squareFeet,
    stagedImageUrl, walkthrough3dUrl, styleApplied,
    comparableCount: comparables.length,
    avgCompPrice, avgPricePerSqft,
    suggestedPriceLow, suggestedPriceHigh, estimatedValueFromComps
  }
};

parameters.text:
=You are a real estate copywriter creating a listing from a newly staged room render and comparable-sales pricing data.

Property:
Address: {{ $json.address }}
Type: {{ $json.propertyType }}
Bedrooms: {{ $json.bedrooms }} | Bathrooms: {{ $json.bathrooms }} | Square Feet: {{ $json.squareFeet }}
Staging Style Applied: {{ $json.styleApplied }}

Comp-Based Pricing ({{ $json.comparableCount }} comparables):
Average Comp Price: ${{ $json.avgCompPrice }}
Average Price per Sqft: ${{ $json.avgPricePerSqft }}
Estimated Value: ${{ $json.estimatedValueFromComps }}
Suggested Price Range: ${{ $json.suggestedPriceLow }} - ${{ $json.suggestedPriceHigh }}

Write a compelling MLS-style listing based on this data.

Return a JSON object with EXACTLY these fields:
{
  "listingTitle": "short punchy headline, under 12 words",
  "listingDescription": "3-4 sentence listing description highlighting the staged look and property features",
  "keySellingPoints": ["point 1", "point 2", "point 3"],
  "suggestedListPrice": number, choose a single price within the suggested range
}

Return ONLY the JSON. No markdown, no explanation.

