const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  const price = item.estimatedValueFromComps || item.avgCompPrice || 0;
  parsed = {
    listingTitle: `${item.propertyType} at ${item.address}`,
    listingDescription: `This ${item.bedrooms}-bed, ${item.bathrooms}-bath ${item.propertyType.toLowerCase()} at ${item.address} has been beautifully staged in a ${item.styleApplied} style. Based on ${item.comparableCount} nearby comparables, it's priced to move.`,
    keySellingPoints: [
      `${item.squareFeet} square feet of living space`,
      `Freshly staged in a ${item.styleApplied} style`,
      `Priced using ${item.comparableCount} nearby comparable sales`
    ],
    suggestedListPrice: price
  };
}

return {
  json: {
    ...item,
    ...parsed
  }
};

const item = $input.item.json;

const packageGeneratedAt = new Date().toISOString();
const sellingPointsText = (item.keySellingPoints || [])
  .map(p => `- ${p}`)
  .join('
');

const listingPackageBody = `${item.listingTitle}
Generated: ${packageGeneratedAt}

${item.address}
${item.propertyType} | ${item.bedrooms} bed | ${item.bathrooms} bath | ${item.squareFeet} sqft

Staged Photo: ${item.stagedImageUrl}
3D Walkthrough: ${item.walkthrough3dUrl}
Staging Style: ${item.styleApplied}

${item.listingDescription}

Key Selling Points:
${sellingPointsText}

Comp-Based Pricing (${item.comparableCount} comparables):
Average Comp Price: $${item.avgCompPrice}
Average Price/Sqft: $${item.avgPricePerSqft}
Suggested Range: $${item.suggestedPriceLow} - $${item.suggestedPriceHigh}

Suggested List Price: $${item.suggestedListPrice}`;

return {
  json: {
    ...item,
    packageGeneratedAt,
    listingPackageBody
  }
};
